{"description":"用 node 反推 EVIDENCE 口径","command":"$script = @'
const fs=require('fs'),crypto=require('crypto');
const files=["docs/99c-来源勘误.md","docs/17-yelan-debunk.md","docs/12-verify.md","docs/16-ladder.md","docs/20-tieba-ego.md"];
const base="./";
for(const f of files){
  const p=base+f; const buf=fs.readFileSync(p); const txt=buf.toString('utf8');
  const i=txt.indexOf('EVIDENCE:');
  const evline=txt.slice(i).split(/\r?\n/)[0];
  const parts=evline.split('|'); const wantB=parts[1], wantH=parts[2];
  const variants={
    rawBody: Buffer.from(txt.slice(0,i),'utf8'),
    bodyNoNL: Buffer.from(txt.slice(0,i).replace(/\r?\n$/,''),'utf8'),
  };
  const out=[f,`total=${buf.length}`,`EV says ${wantB}/${wantH}`];
  for(const [k,v] of Object.entries(variants)){
    const h=crypto.createHash('sha256').update(v).digest('hex').slice(0,12);
    out.push(`${k}: bytes=${v.length} hash=${h} matchB=${v.length==wantB} matchH=${h.toLowerCase()==String(wantH).toLowerCase()}`);
  }
  console.log(out.join('\n  ')+'\n');
}
'@
$tmp = Join-Path $env:TEMP "ev-probe.cjs"
[System.IO.File]::WriteAllText($tmp, $script, [System.Text.UTF8Encoding]::new($false))
node $tmp"}

