const fs=require('fs');
const base="./";
for(const f of ["docs/99c-来源勘误.md","docs/20-tieba-ego.md","README.md"]){
  const b=fs.readFileSync(base+f);
  const bom = b[0]===0xEF&&b[1]===0xBB&&b[2]===0xBF;
  const crlf=(b.toString('utf8').match(/\r\n/g)||[]).length;
  const lf=(b.toString('utf8').match(/(?<!\r)\n/g)||[]).length;
  console.log(f,'bom='+bom,'crlf='+crlf,'lf_only='+lf);
}
const src="./";
const sb=fs.readFileSync(src);
console.log('SOURCE bom='+(sb[0]===0xEF&&sb[1]===0xBB&&sb[2]===0xBF), 'crlf='+(sb.toString('utf8').match(/\r\n/g)||[]).length, 'lf_only='+(sb.toString('utf8').match(/(?<!\r)\n/g)||[]).length);
'@
$tmp = Join-Path $env:TEMP "enc-probe.cjs"
[System.IO.File]::WriteAllText($tmp, $script, [System.Text.UTF8Encoding]::new($false))
