{"description":"复制并按规则脱敏 98 文档","command":"$script = @'
const fs=require('fs'),crypto=require('crypto');
const src="./";
const dst="./";
let txt=fs.readFileSync(src,'utf8');
const i=txt.indexOf('EVIDENCE:');
if(i<0) throw new Error('no EVIDENCE line');
let body=txt.slice(0,i);
// 脱敏：本机绝对/工作区路径归一到仓库内相对路径
body=body.replace(/research\\\\20261126-genshin74\\\\/g,'docs/');
if(/用户|用户|账号标识|fil./|./|./|./)) throw new Error('still dirty: '+body.match(/用户|用户|账号标识|fil./|./|./|./));
const buf=Buffer.from(body,'utf8');
const h=crypto.createHash('sha256').update(buf).digest('hex').slice(0,12);
const ev=`EVIDENCE: docs/98-调度统筹实战复盘.md|${buf.length}|${h}`;
fs.writeFileSync(dst, body+ev+'\n', 'utf8');
console.log('bodyBytes='+buf.length+' hash='+h);
console.log('fileBytes='+fs.statSync(dst).size);
console.log('lines='+fs.readFileSync(dst,'utf8').split('\n').length);
'@
$tmp = Join-Path $env:TEMP "copy98.cjs"
[System.IO.File]::WriteAllText($tmp, $script, [System.Text.UTF8Encoding]::new($false))
node $tmp"}

