  $n = (Select-String -LiteralPath $f -Pattern $p -SimpleMatch -AllMatches | ForEach-Object { $_.Matches.Count } | Measure-Object -Sum).Sum
  if (-not $n) { $n = 0 }
  "$p => $n"
}"}

